const n = Number(nLine);
const parent = Array.from({ length: n }, (_, i) => i);

function find(x) {
  while (parent[x] !== x) {
    x = parent[x];
  }
  return x;
}

function union(a, b) {
  const rootA = find(a);
  const rootB = find(b);
  if (rootA !== rootB) {
    parent[rootB] = rootA;
  }
}

for (const line of lines) {
  const [command, a, b] = line.trim().split(/\s+/);
  if (command === "link") {
    union(Number(a), Number(b));
  } else {
    const same = find(Number(a)) === find(Number(b));
    console.log(`${a} ${b}: ${same ? "yes" : "no"}`);
  }
}

