    parent[x] = parent[parent[x]];
    x = parent[x];
  }
  return x;
}

function union(a, b) {
  let rootA = find(a);
  let rootB = find(b);
  if (rootA === rootB) {
    return false;
  }
  if (size[rootA] < size[rootB]) {
    [rootA, rootB] = [rootB, rootA];
  }
  parent[rootB] = rootA;
  size[rootA] += size[rootB];
