const input = require("fs").readFileSync(0, "utf8");
const [nLine, ...lines] = input.trim().split("\n");
const n = Number(nLine);
const parent = Array.from({ length: n }, (_, i) => i);
const size = new Array(n).fill(1);

function find(x) {
  while (parent[x] !== x) {
    parent[x] = parent[parent[x]];
    x = parent[x];
  }
  return x;
}

function union(a, b) {
  let rootA = find(a);
  let rootB = find(b);
  if (rootA === rootB) {
    return false;
  }
  if (size[rootA] < size[rootB]) {
    [rootA, rootB] = [rootB, rootA];
  }
  parent[rootB] = rootA;
  size[rootA] += size[rootB];
  return true;
}

let extra = null;
for (const line of lines) {
  const [a, b] = line.trim().split(/\s+/).map(Number);
  if (!union(a, b)) {
    extra = [a, b];
    break;
  }
}
console.log(extra === null ? "no extra cable" : `extra cable: ${extra[0]} ${extra[1]}`);

