const input = require("fs").readFileSync(0, "utf8");
const [nLine, ...lines] = input.trim().split("\n");
const n = Number(nLine);
const links = lines.map((line) => line.trim().split(/\s+/).map(Number));
const parent = Array.from({ length: n }, (_, i) => i);
const size = new Array(n).fill(1);

function find(x) {
  while (parent[x] !== x) {
    parent[x] = parent[parent[x]];
    x = parent[x];
  }
  return x;
}

function union(a, b) {
  let rootA = find(a);
  let rootB = find(b);
  if (rootA === rootB) {
    return false;
  }
  if (size[rootA] < size[rootB]) {
    [rootA, rootB] = [rootB, rootA];
  }
  parent[rootB] = rootA;
  size[rootA] += size[rootB];
  return true;
}

let kept = 0;
let total = 0;
links.sort((x, y) => x[2] - y[2]);
for (const [a, b, cost] of links) {
  if (union(a, b)) {
    console.log(`${a} ${b} ${cost}`);
    kept++;
    total += cost;
  }
}
console.log(kept === n - 1 ? `total ${total}` : "cannot connect everything");
